import React from 'react';
import { LogOut } from 'lucide-react';
import logo from '../../assets/logo.png';
import { useAuth } from '../../context/AuthContext';
import { getTheme } from '../../constants/Theme';
import { useNavigate } from 'react-router-dom';
import { BASE_URL, API_ENDPOINTS } from '../../config';


export default function AppHeader() {
  const { user, logout, updateUser } = useAuth();
  const theme = getTheme(user?.role);
  const navigate = useNavigate();
  const handleLogoClick = () => {
    navigate('/dashboard');
    setTimeout(() => {
      if (window.location.hash.includes('dashboard') && !document.querySelector('.hr-dashboard-container')) {
        window.location.reload();
      }
    }, 150);
  };
  const [winWidth, setWinWidth] = React.useState(window.innerWidth);
  const [showLogoutModal, setShowLogoutModal] = React.useState(false);

  React.useEffect(() => {
    const handleResize = () => setWinWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const [fetchedRole, setFetchedRole] = React.useState('');

  React.useEffect(() => {
    const fetchUserData = async () => {
      const userRole = user?.role?.toLowerCase() || '';
      const isAdmin = ['admin', 'manager', 'lead', 'teamleader', 'ceo', 'hr'].includes(userRole);
      const token = localStorage.getItem('token') || user?.token;
      
      if (!token) {
        setFetchedRole(user?.role || user?.Role || '');
        return;
      }

      try {
        // Fetch own profile to ensure header has the latest profile pic globally
        const currentId = user?.employee_id || user?.id || user?.empId;
        if (currentId) {
          const profileRes = await fetch(`${API_ENDPOINTS.PROFILE || `${BASE_URL}/api/employee-profile`}/${currentId}`, {
            headers: { 'Authorization': `Bearer ${token}` }
          });
          if (profileRes.ok) {
            const pData = await profileRes.json();
            const pic = pData.profile_pic || pData.profile_picture;
            if (pic && user?.profile_pic !== pic && typeof updateUser === 'function') {
              updateUser({ profile_pic: pic });
            }
          }
        }
      } catch (err) {
        console.error("Fetch Profile Error:", err);
      }

      if (!isAdmin) {
        setFetchedRole(user?.role || user?.Role || '');
        return;
      }

      try {
        const res = await fetch(API_ENDPOINTS.USERS || `${BASE_URL}/api/users`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (res.ok) {
          const data = await res.json();
          const users = Array.isArray(data) ? data : (data.value || []);
          const currentId = user?.employee_id || user?.id || user?.empId || '202515';
          const target = users.find(u => String(u.employee_id || u.id || u.empId) === String(currentId));
          if (target) {
            setFetchedRole(target.Role || target.role);
          }
        }
      } catch (err) {
        console.error("Fetch Role Error:", err);
      }
    };
    fetchUserData();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.employee_id, user?.id, user?.token]);

  const styles = {
    header: {
      height: winWidth < 768 ? '70px' : '85px',
      backgroundColor: '#a7d6da', // Pastel Teal Header Background
      borderBottom: '1.5px solid rgba(0, 0, 0, 0.05)', // Subtle contrast line
      display: 'grid',
      gridTemplateColumns: 'auto 1fr auto',
      alignItems: 'center',
      padding: winWidth < 768 ? '0 16px' : '0 26px',
      gap: '10px',
      boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      zIndex: 2000,
    },
    left: { display: 'flex', alignItems: 'center', gap: '12px' },
    center: { display: 'flex', justifyContent: 'center', alignItems: 'center' },
    logoImg: { height: winWidth < 768 ? '35px' : '45px', objectFit: 'contain', filter: 'brightness(0) invert(1)' },
    userName: { color: '#1e293b', fontWeight: '800', fontSize: winWidth < 768 ? '15px' : '18px' },
    designation: { color: '#4b5563', fontWeight: '700', fontSize: '9px', textTransform: 'uppercase' },
    navActions: { display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '20px' },
    badge: {
      position: 'absolute',
      top: '-5px',
      right: '-5px',
      backgroundColor: '#ef4444',
      color: 'white',
      borderRadius: '50%',
      width: '18px',
      height: '18px',
      fontSize: '10px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontWeight: 'bold',
      border: '2px solid #3863a8'
    }
  };

  return (
    <div className="app-header-container" style={styles.header}>
      <div style={{ ...styles.left, paddingRight: '20px' }}>
        <div
          onClick={handleLogoClick}
          style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}
        >
          <img
            src={logo}
            alt="Navabharatha"
            style={{
              height: winWidth < 768 ? '65px' : '85px',
              width: 'auto',
              objectFit: 'contain'
            }}
          />
        </div>
      </div>

      <div 
        onClick={handleLogoClick}
        style={{ ...styles.center, cursor: 'pointer' }}
      >
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          fontSize: '35px',
          fontWeight: '950',
          letterSpacing: '0px',
          textTransform: 'uppercase',
          fontFamily: "'Outfit', sans-serif",
          background: 'linear-gradient(135deg, #1e293b 0%, #334155 100%)',
          WebkitBackgroundClip: 'text',
          WebkitTextFillColor: 'transparent',
          position: 'relative'
        }}>
          NBT HUB
        </div>
      </div>

      <div style={styles.navActions}>

        {/* User Info moved here */}
        <div style={{ display: winWidth < 600 ? 'none' : 'block', textAlign: 'right', lineHeight: '1.2' }}>
          <div style={styles.userName}>{user?.name || 'NBT User'}</div>
          <div style={styles.designation}>{fetchedRole || theme.label}</div>
        </div>

        <div style={{ position: 'relative', width: winWidth < 768 ? '48px' : '64px', height: winWidth < 768 ? '48px' : '64px' }}>
          <div
            onClick={() => navigate('/personal-info?self=true')}
            style={{
              width: '100%',
              height: '100%',
              borderRadius: '50%',
              background: 'rgba(0,0,0,0.05)', border: '1px solid rgba(0,0,0,0.1)',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer', transition: '0.2s transform',
              overflow: 'hidden', position: 'relative'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
          >
            {(() => {
              const empId = user?.employee_id || user?.id || user?.empId;
              const rawPic = user?.profile_pic;
              const photoUrl = rawPic ? (rawPic.startsWith('http') || rawPic.startsWith('data:') ? rawPic : `${BASE_URL}${rawPic.startsWith('/') ? '' : '/'}${rawPic}`) : null;
              return (
                <>
                  {photoUrl && (
                    <img
                      src={photoUrl}
                      alt="Profile"
                      style={{ width: '100%', height: '100%', objectFit: 'cover', position: 'absolute', top: 0, left: 0 }}
                      onError={(e) => e.target.style.display = 'none'}
                    />
                  )}
                  <svg width={winWidth < 768 ? "18" : "22"} height={winWidth < 768 ? "18" : "22"} viewBox="0 0 24 24" fill="none" stroke="#1e293b" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ position: 'relative', zIndex: -1 }}><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" /><circle cx="12" cy="7" r="4" /></svg>
                </>
              );
            })()}
          </div>

          <div
            onClick={(e) => {
              e.stopPropagation();
              setShowLogoutModal(true);
            }}
            style={{
              position: 'absolute',
              bottom: '-2px',
              right: '-2px',
              background: '#ef4444',
              width: winWidth < 768 ? '20px' : '24px',
              height: winWidth < 768 ? '20px' : '24px',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
              cursor: 'pointer',
              zIndex: 10,
              border: '2px solid white'
            }}
            title="Logout"
          >
            <LogOut size={winWidth < 768 ? 10 : 12} color="white" strokeWidth={3} style={{ marginLeft: '-1px' }} />
          </div>
        </div>
      </div>

      {/* Custom Logout Modal */}
      {showLogoutModal && (
        <div style={{
          position: 'fixed',
          top: 0, left: 0, right: 0, bottom: 0,
          backgroundColor: 'rgba(0,0,0,0.5)',
          backdropFilter: 'blur(8px)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 3000,
          padding: '20px'
        }}>
          <div style={{
            background: 'white',
            padding: '32px',
            borderRadius: '24px',
            width: '100%',
            maxWidth: '380px',
            textAlign: 'center',
            boxShadow: '0 25px 50px -12px rgba(0,0,0,0.25)',
            transform: 'scale(1)',
            animation: 'modalIn 0.3s ease-out'
          }}>
            <div style={{
              width: '64px', height: '64px', background: '#fee2e2', borderRadius: '50%',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              margin: '0 auto 20px', color: '#ef4444'
            }}>
              <LogOut size={32} />
            </div>
            <h2 style={{ fontSize: '24px', fontWeight: '800', color: '#1e293b', marginBottom: '8px' }}>Confirm Logout</h2>
            <p style={{ color: '#64748b', fontSize: '15px', fontWeight: '600', marginBottom: '32px' }}>
              Are you sure you want to log out of your NBT HUB account?
            </p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button
                onClick={() => setShowLogoutModal(false)}
                style={{
                  flex: 1, padding: '14px', borderRadius: '16px', border: '1.5px solid #e2e8f0',
                  background: 'white', color: '#64748b', fontWeight: '800', cursor: 'pointer',
                  transition: '0.2s'
                }}
                onMouseOver={(e) => e.currentTarget.style.background = '#f8fafc'}
                onMouseOut={(e) => e.currentTarget.style.background = 'white'}
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  logout();
                  navigate('/login');
                }}
                style={{
                  flex: 1, padding: '14px', borderRadius: '16px', border: 'none',
                  background: '#ef4444', color: 'white', fontWeight: '800', cursor: 'pointer',
                  boxShadow: '0 10px 15px -3px rgba(239, 68, 68, 0.3)',
                  transition: '0.2s'
                }}
                onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
                onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
              >
                Log Out
              </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        @keyframes modalIn {
          from { opacity: 0; transform: scale(0.9) translateY(20px); }
          to { opacity: 1; transform: scale(1) translateY(0); }
        }
      `}</style>
    </div>
  );
}
